<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationAcceptedByVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

final class UserInvitationAcceptedByVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new UserRef('one');
        $ref = UserInvitationAcceptedByVO::from($value);
        $this->assertEquals(new UserRef('one'), $ref->value());
        $other = UserInvitationAcceptedByVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = UserInvitationAcceptedByVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = UserInvitationAcceptedByVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(UserInvitationAcceptedByVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = UserInvitationAcceptedByVO::from(new UserRef('one'));
        $same = UserInvitationAcceptedByVO::from(new UserRef('one'));
        $other = UserInvitationAcceptedByVO::from(new UserRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = UserInvitationAcceptedByVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = UserInvitationAcceptedByVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
